import { DashboardIcon } from '@sanity/icons/Dashboard'
import { defineField, defineType } from 'sanity'

import { sanitizeSvgWithReport } from '@/lib/svg-sanitize'
import { InfographicInput } from '@/sanity/components/infographic-input'

/**
 * An infographic generated by AI from the whole post, as two inline SVG variants: wide (tablet and desktop) and
 * narrow (phones). The "Generate" button in the block (InfographicInput) sends the shared instructions
 * (`infographic-settings`), the technical rules and the article to Sanity Agent Actions, checks both SVGs with the
 * sanitiser and fills the block. Any diagram type the instructions allow: hub, bar, stats, timeline and so on.
 *
 * The SVGs are not hand-editable: they are hidden and shown as a preview in the button's panel. Title and
 * description are filled by the AI and stay editable; the site prints them above the diagram and puts them in the
 * SVG's own `<title>` and `<desc>`. `generation` keeps what the AI last wrote, so Regenerate can tell whether the
 * editor has changed the title or description since.
 */

const svgField = (name: 'wide' | 'narrow', title: string) =>
  defineField({
    name,
    title,
    type: 'string',
    hidden: true,
    readOnly: true,
    // Checked again on the site before render: the Content API accepts writes that never ran Studio code.
    validation: (Rule) =>
      Rule.custom((value: string | undefined) => {
        if (!value) {
          return 'Generate the infographic with the button in the block.'
        }

        const report = sanitizeSvgWithReport(value)

        return report.svg ? true : `The ${name} diagram fails the SVG check (${report.error}). Regenerate the infographic.`
      }),
  })

export const infographic = defineType({
  name: 'infographic',
  title: 'Infographic',
  type: 'object',
  icon: DashboardIcon,
  components: { input: InfographicInput },
  fields: [
    defineField({
      name: 'eyebrow',
      title: 'Eyebrow',
      type: 'string',
      description: 'Small text above the title. Generate never changes it.',
      initialValue: 'Article infographic',
      validation: (Rule) => Rule.required(),
    }),
    defineField({
      name: 'title',
      title: 'Title',
      type: 'string',
      description: 'Heading above the diagram. Filled by Generate; edit it if needed.',
      validation: (Rule) => Rule.required(),
    }),
    defineField({
      name: 'description',
      title: 'Description',
      type: 'text',
      rows: 3,
      description:
        'Shown under the title and read out by screen readers in place of the diagram, so it states everything the diagram shows. Filled by Generate; edit it if needed.',
      validation: (Rule) => Rule.required(),
    }),
    svgField('wide', 'Wide diagram (SVG)'),
    svgField('narrow', 'Narrow diagram (SVG)'),
    defineField({
      name: 'generation',
      title: 'Last generation',
      type: 'object',
      hidden: true,
      readOnly: true,
      description: 'What the AI last wrote, to tell whether the editor has changed a text since.',
      fields: [
        defineField({ name: 'type', title: 'Diagram type', type: 'string' }),
        defineField({ name: 'generatedAt', title: 'Generated at', type: 'datetime' }),
        defineField({ name: 'title', title: 'Title', type: 'string' }),
        defineField({ name: 'description', title: 'Description', type: 'text' }),
      ],
    }),
  ],
  preview: {
    select: { title: 'title', type: 'generation.type', wide: 'wide' },
    prepare({ title, type, wide }: { title?: string; type?: string; wide?: string }) {
      return {
        title: title || 'Infographic',
        subtitle: wide ? `Infographic · ${type || 'diagram'}` : 'Infographic · not generated yet',
        media: DashboardIcon,
      }
    },
  },
})
